class Unrenderable(ValueError):
    """Nothing can be rendered from what the repository holds (its manifest is not valid); the render stops instead of guessing, and the caller
    records the reason (a boot stage is degraded, the command exits 1). A fact one surface lacks only holds that surface back (problems)."""

    def __init__(self, problems: list[str]):
        super().__init__("\n".join(problems))
        self.problems = problems


# REUSE-IgnoreStart  (the copyright lines below are patterns that read LICENSE, not this file's own)
def holder(root=HERE) -> dict:
    """The copyright holder, read from LICENSE: its "Licensor:" line, else a "Copyright (c) YEAR NAME" line, else the first author of CITATION.cff.
    {} when none names one; it is never guessed. The year is the LICENSE "Effective:" year (or the copyright line's) when one is written."""
    root = Path(root)
    lic = root / "LICENSE"
    t = lic.read_text(encoding="utf-8", errors="replace") if lic.is_file() else ""
    eff = re.search(r"^\s*Effective:\s*(\d{4})", t, re.M)
    m = re.search(r"^\s*Licensor:\s*(.+)$", t, re.M)
    if m:
        name = re.split(r"\s*[(,;]", m.group(1), maxsplit=1)[0].strip()
        orcid = re.search(r"ORCID[:\s]*(\d{4}-\d{4}-\d{4}-\d{3}[\dX])", m.group(1))
        if name:
            return {"name": name, "orcid": orcid.group(1) if orcid else None, "year": eff.group(1) if eff else None, "from": "LICENSE"}
    c = re.search(r"^\s*Copyright\s*(?:\(c\)|©)?\s*(\d{4})(?:\s*[-,]\s*\d{4})*,?\s+([^<>\n]+?)\.?\s*$", t, re.M | re.I)
    # REUSE-IgnoreEnd
    if c:
        return {"name": c.group(2).strip(), "orcid": None, "year": eff.group(1) if eff else c.group(1), "from": "LICENSE"}
    cit = root / "CITATION.cff"
    lines = cit.read_text(encoding="utf-8").splitlines() if cit.is_file() else []
    if "authors:" in [x.rstrip() for x in lines]:
        first: dict = {}
        for x in lines[[y.rstrip() for y in lines].index("authors:") + 1:]:
            if x and not x[0].isspace() and not x.startswith("-"):
                break  # the next top-level key
            if x.lstrip().startswith("- ") and first:
                break  # the second author
            kv = re.match(r"([a-z-]+):\s*\"?(.*?)\"?\s*$", x.lstrip(" -"))
            if kv:
                first[kv.group(1)] = kv.group(2)
        name = first.get("name") or " ".join(v for v in (first.get("given-names"), first.get("family-names")) if v)
        if name:
            return {"name": name, "orcid": None, "year": eff.group(1) if eff else None, "from": "CITATION.cff"}
    return {}


def license_text(root=HERE) -> str | None:
    p = Path(root) / "LICENSE"
    return p.read_text(encoding="utf-8") if p.is_file() else None


def license_url(i: dict) -> str:
    """Where the licence text is read: the SPDX page for a listed licence, the repository's LICENSE for a LicenseRef."""
    return f"https://github.com/{i['repo']}/blob/main/LICENSE" if i["license"].startswith("LicenseRef-") else f"https://spdx.org/licenses/{i['license']}.html"


def short(text: str, n: int) -> str:
    """At most n characters, cut at a sentence or a word, never mid-word."""
    s = " ".join(str(text).split())
    if len(s) <= n:
        return s
    first = re.match(r"(.+?[.!?])(\s|$)", s)
    if first and len(first.group(1)) <= n:
        return first.group(1)
    return s[:n - 1].rsplit(" ", 1)[0].rstrip(",;:") + "…"


# --- a JSON Schema validator for the subset the manifest schema uses (no third-party package) ---
def validate(value, schema, path="$") -> list[str]:
    errs = []
    t = schema.get("type")
    if t:
        names = {"object": dict, "array": list, "string": str, "boolean": bool, "null": type(None), "number": (int, float), "integer": int}
        ok = any(isinstance(value, names[x]) and not (x in ("number", "integer") and isinstance(value, bool)) for x in ([t] if isinstance(t, str) else t))
        if not ok:
            return [f"{path}: must be {t}"]
    if "enum" in schema and value not in schema["enum"]:
        errs.append(f"{path}: must be one of {', '.join(map(str, schema['enum']))}")
    if isinstance(value, str):
        if len(value) < schema.get("minLength", 0):
            errs.append(f"{path}: shorter than {schema['minLength']} characters")
        if len(value) > schema.get("maxLength", 10 ** 9):
            errs.append(f"{path}: longer than {schema['maxLength']} characters ({len(value)})")
        if "pattern" in schema and not re.search(schema["pattern"], value):
            errs.append(f"{path}: does not match {schema['pattern']}")
    if isinstance(value, list):
        if len(value) > schema.get("maxItems", 10 ** 9):
            errs.append(f"{path}: more than {schema['maxItems']} items")
        if schema.get("uniqueItems") and len({json.dumps(x, sort_keys=True) for x in value}) != len(value):
            errs.append(f"{path}: items repeat")
        for i, x in enumerate(value):
            errs += validate(x, schema.get("items", {}), f"{path}[{i}]")
    if isinstance(value, dict):
        for k in schema.get("required", []):
            if k not in value:
                errs.append(f"{path}.{k}: required")
        props = schema.get("properties", {})
        for k, v in value.items():
            if k in props:
                errs += validate(v, props[k], f"{path}.{k}")
            elif schema.get("additionalProperties") is False:
                errs.append(f"{path}.{k}: not a manifest field" + (" (the stage is computed from evidence, never typed)" if k == "stage" else ""))
    return errs


def schema(root=HERE) -> dict:
    for p in (Path(root) / "standards/system.schema.json", Path(root) / "seed/standards/system.schema.json", HERE / "standards/system.schema.json"):
        if p.is_file():
            return json.loads(p.read_text(encoding="utf-8"))
    raise FileNotFoundError("standards/system.schema.json")


def load(root=HERE) -> dict:
    return json.loads((Path(root) / MANIFEST).read_text(encoding="utf-8"))


def identity(root=HERE) -> dict:
    return load(root).get("identity") or {}


def check_manifest(root=HERE) -> list[str]:
    p = Path(root) / MANIFEST
    if not p.is_file():
        return [f"{MANIFEST}: missing; every repository carries one manifest with an identity object"]
    m = load(root)
    errs = [f"{MANIFEST} {e}" for e in validate(m, schema(root))]
    i, org = m.get("identity") or {}, m.get("org") or {}
    for key, want in (("name", i.get("name")), ("slug", i.get("slug"))):
        if org.get(key) and want and org[key] != want:
            errs.append(f"{MANIFEST} org.{key} is {org[key]!r} and identity.{key} is {want!r}: one name, one slug")
    return errs


def stage(root=HERE) -> str:
    """The lifecycle stage, computed by scripts/seedlife.py from evidence when the system carries it; never read from the manifest."""
    f = Path(root) / "ops/seed-lifecycle.json"
    if f.is_file():
        try:
            j = json.loads(f.read_text(encoding="utf-8"))
            s = j.get("stage") or next((v.get("stage") for v in (j.get("seeds") or {}).values() if isinstance(v, dict)), None)
            if s in LIFECYCLE:
                return s
        except (ValueError, AttributeError):
            pass
    return "unmeasured"


# --- blocks ---
def _block(name: str, body: list[str]) -> str:
    return "\n".join([f"<!-- {name}:start (generated by scripts/surfaces.py from {MANIFEST}; do not edit) -->", *body, f"<!-- {name}:end -->"]) + "\n"


def _re(name: str):
    return re.compile(rf"<!-- {name}:start[^>]*-->.*?<!-- {name}:end -->\n?", re.S)


def identity_block(i: dict) -> str:
    parent = f" It runs on [Ultrastable]({PLATFORM}/), the foundation for any autonomous system." if i.get("layer") in ("seeded-system", "tenant") else ""
    return _block("identity", [f"**{i['name']}.** {i['summary']}{parent}"])


def runs_text(r: dict) -> str:
    kind = {"worker": "Cloudflare Worker", "pages": "Cloudflare Pages project", "actions": "GitHub Actions workflow", "container": "container", "function": "function"}[r["kind"]]
    return f"{kind} `{r['name']}`" + (f", {r['how']}" if r.get("how") else "")


def live_block(i: dict) -> str:
    """The same block foundation/livelinks.py writes from the platform's registries, computed here from the manifest alone."""
    o = i.get("public_url")
    if i.get("layer") in ("template", "admin", "org-profile") and not o:
        return ""  # nothing deploys from it; a template names a running example instead (the platform writes that block)
    if not o:
        return "\n".join([LIVE_START, "## Live", "", "Not deployed yet. This repository holds the system's manifest; when its first version is deployed, this block names where it runs.",
                          "", f"Runs on [Ultrastable]({PLATFORM}/), the foundation for any autonomous system.", LIVE_END]) + "\n"
    body = ["## Live", "", f"**Running at [{o}]({o}/)**", "", "| | |", "|---|---|", f"| Health report | [{o}/health]({o}/health) |",
            f"| What it states, and the endpoint behind each statement | [{o}/claims.json]({o}/claims.json) |"]
    if i.get("runs_as"):
        body.append(f"| Runs as | {runs_text(i['runs_as'][0])} |")
    if i.get("layer") != "platform":
        body.append(f"| Platform | [Ultrastable]({PLATFORM}/), the foundation for any autonomous system · [every system running on it]({PLATFORM}/directory) |")
    else:
        body.append(f"| Every system running on it | [{PLATFORM}/directory]({PLATFORM}/directory) |")
    return "\n".join([LIVE_START, *body, LIVE_END]) + "\n"


def deploy_button(i: dict) -> str:
    """Cloudflare's Deploy to Cloudflare button for this repository's root (https://developers.cloudflare.com/workers/platform/deploy-buttons/)."""
    return f"[![Deploy to Cloudflare](https://deploy.workers.cloudflare.com/button)](https://deploy.workers.cloudflare.com/?url=https://github.com/{i['repo']})"


def how_block(i: dict, st: str, button: bool = False) -> str:
    o = i.get("public_url")
    where = (lambda path, text: f"[{text}]({o}{path})") if o else (lambda path, text: f"`{path}`")
    body = ["## How this system runs", "",
            f"**What it is.** {i['summary']}", ""]
    if i.get("loop"):
        body += [f"**The loop it closes.** {i['loop']}", ""]
    if i.get("layer") in ("seeded-system", "template", "platform"):
        body += ["**How it bootstraps.** One file, `IDEA.md`, states the idea and its system test (a loop to close, a measure that can be wrong, upkeep that never ends, "
                 "a running cost the owner accepts). `bootstrap/bootstrap.py` reads it with `ultrastable.json` and `autonomy/policy.json`, qualifies the idea, hires the roles, "
                 "writes the Worker's configuration and database, and deploys the tick Worker. No person runs a command.", ""]
        if button:  # a public repository with a root Wrangler configuration: one click deploys a copy into the clicker's own Cloudflare account
            body += ["**Run your own copy.** " + deploy_button(i), ""]
    elif i.get("layer") == "tenant":
        body += [f"**How it bootstraps.** It is a tenant of the platform ([{i.get('parent') or 'ultrastable/ultrastable'}](https://github.com/{i.get('parent') or 'ultrastable/ultrastable'})): "
                 "its manifest is registered there, this repository holds its code, and the platform builds this repository's `main` into its Worker.", ""]
    if i.get("runs_as"):
        body += ["**How it runs.** " + "; ".join(runs_text(r) + (f" at {', '.join(r['routes'])}" if r.get("routes") else "") for r in i["runs_as"]) +
                 ". Work is taken, done, verified and recorded by the system's own loops on a clock; a session or a person only adds ideas.", ""]
    if i.get("layer") in ("seeded-system", "template", "platform"):  # a tenant's starter Worker serves /health and /claims.json, no ignition or /live
        body += ["**How it becomes autonomous.** Two ladders, both computed from evidence the system records, never declared:", "",
                 "- ignition (read every tick, reported at " + where("/health", "/health") + "): " + " → ".join(f"`{s}`" for s in IGNITION) +
                 ". `instrumented` and above means bootstrapped; the first unmet stage is filed as its own work item.",
                 "- lifecycle (`scripts/seedlife.py`): " + " → ".join(f"`{s}`" for s in LIFECYCLE) + f". Stage at the last reading: `{st}`. "
                 "`autonomous` needs every one-year survival question answered (credentials, budget, dependencies, models, health, backups, renewal, improvement, privacy).", "",
                 "**How criticality is read.** k = verified deploys / (normalized cost + human touches), logged every tick and served at " + where("/live", "/live") +
                 " (`k_eff`, and `k_self` for deploys the system originated itself). At or above 1 with `k_self` carrying it, the system is self-sustaining.", ""]
    return _block("how", body[:-1] if body[-1] == "" else body)


def render_readme(text: str, i: dict, st: str, button: bool = False) -> str:
    """Title, identity, Live, then the rest; How this system runs is replaced in place or appended. Running it twice changes nothing."""
    blocks = {"identity": identity_block(i), "how": how_block(i, st, button)}
    live = live_block(i)
    rest = text
    for name in blocks:
        rest = _re(name).sub("", rest, count=1)
    rest = LIVE_RE.sub("", rest, count=1)
    h = re.search(r"^# .*\n", rest, re.M)
    body = (rest[h.end():] if h else rest).strip("\n")
    title = h.group(0) if h else f"# {i['name']}\n"
    out = f"{title}\n{blocks['identity']}\n" + (live + "\n" if live else "") + (body + "\n\n" if body else "") + blocks["how"]
    return out


def features(i: dict) -> list[str]:
    """What the system does, computed from the manifest: the same facts the README's How block states, never typed per system."""
    o, layer, f = i.get("public_url"), i.get("layer"), []
    if i.get("loop"):
        f.append(i["loop"].rstrip(". "))  # the loop it closes, in the manifest's own words
    if layer in ("seeded-system", "template", "platform"):
        f.append("Starts from one file, IDEA.md, in its owner's words; no person runs a command")
    f += ["Runs as " + runs_text(r).replace("`", "") for r in i.get("runs_as") or []]
    if o:
        f += [f"Reports its health at {o}/health", f"Lists what it states, and the endpoint behind each statement, at {o}/claims.json"]
    if layer in ("seeded-system", "template", "platform"):
        f += ["Reads its own stage every tick, from unseeded to self-sustaining", "Logs its criticality every tick: verified deploys against cost and human touches"]
    return f or [i["summary"]]


def long_description(i: dict) -> str:
    """publiccode.yml's longDescription (150 to 10000 characters): identity.description when the manifest carries one, else the summary and the
    loop, then the features they do not already say when those are shorter. Never padded: no sentence is said twice."""
    if i.get("description"):
        return i["description"]
    text = "\n\n".join(x for x in (i["summary"], i.get("loop")) if x)
    extra = [x for x in features(i) if x not in (i["summary"], (i.get("loop") or "").rstrip(". "))]
    if len(text) < 150 and extra:
        text += "\n\n" + "\n".join("- " + x for x in extra)
    return text


def publiccode(i: dict, st: str, h: dict) -> str:
    """publiccode.yml (https://publiccodeyml.github.io/v0/). publiccodeYmlVersion "0" is the form the reference parser (italia/publiccode-parser-go)
    asks for; the maintenance contact and the main copyright owner are the holder LICENSE names (`holder`)."""
    status = {"live": "stable", "planned": "concept", "retired": "obsolete"}.get(i.get("status", "live"), "development")
    q = lambda s: json.dumps(str(s), ensure_ascii=False)  # noqa: E731  JSON strings are YAML strings
    lines = ["# Generated by scripts/surfaces.py from ultrastable.json and LICENSE; do not edit. https://publiccodeyml.github.io/v0/", "publiccodeYmlVersion: \"0\"",
             f"name: {q(i['name'])}", f"url: {q('https://github.com/' + i['repo'])}"]
    if i.get("public_url"):
        lines.append(f"landingURL: {q(i['public_url'])}")
    lines += ["platforms:", "  - web", f"developmentStatus: {status}", "softwareType: standalone/web", "legal:", f"  license: {q(i['license'])}",
              f"  mainCopyrightOwner: {q(h['name'])}", "maintenance:", "  type: internal", "  contacts:", f"    - name: {q(h['name'])}",
              "localisation:", "  localisationReady: false", "  availableLanguages:", "    - en", "description:", "  en:",
              f"    shortDescription: {q(short(i['summary'], 150))}", f"    longDescription: {q(long_description(i))}", "    features:"]
    lines += [f"      - {q(x)}" for x in features(i)]
    return "\n".join(lines) + "\n"


def catalog(i: dict, st: str) -> str:
    """Backstage descriptor (backstage.io/v1alpha1): what this system is, for any software catalog that reads catalog-info.yaml. A Component
    of the one System `ultrastable`, with a `website` type when it serves a public address and `service` otherwise. STANDARDS-FIRST-1."""
    q = lambda s: json.dumps(str(s), ensure_ascii=False)  # noqa: E731  JSON strings are YAML strings
    org, name = i["repo"].split("/", 1)
    lifecycle = {"live": "production", "planned": "experimental", "retired": "deprecated"}.get(i.get("status", "live"), "experimental")
    kind = {"platform": "service", "template": "template", "admin": "documentation", "org-profile": "documentation"}.get(i.get("layer"), "website" if i.get("public_url") else "service")
    meta = re.sub(r"[^a-zA-Z0-9_.-]+", "-", i["slug"]).strip("-._")[:63] or "system"
    lines = ["# Generated by scripts/surfaces.py from ultrastable.json; do not edit. https://backstage.io/docs/features/software-catalog/descriptor-format",
             "apiVersion: backstage.io/v1alpha1", "kind: Component", "metadata:", f"  name: {meta}", f"  title: {q(i['name'])}", f"  description: {q(i['summary'])}",
             "  annotations:", f"    github.com/project-slug: {i['repo']}", f"    backstage.io/source-location: {q('url:https://github.com/' + i['repo'])}"]
    tags = [t for t in sorted(i.get("topics") or []) if re.fullmatch(r"[a-z0-9:+#]+(-[a-z0-9:+#]+)*", t) and len(t) <= 63]
    if tags:
        lines += ["  tags:"] + [f"    - {t}" for t in tags]
    links = [("Source", "https://github.com/" + i["repo"], "github")]
    if i.get("public_url"):
        u = i["public_url"]
        links = [("Live", u, "web"), ("Health report", u + "/health", "dashboard"), ("What it states", u + "/claims.json", "docs")] + links
    lines += ["  links:"] + [x for t, u, ic in links for x in (f"    - url: {q(u)}", f"      title: {q(t)}", f"      icon: {ic}")]
    lines += ["spec:", f"  type: {kind}", f"  lifecycle: {lifecycle}", f"  owner: {q('group:default/' + org)}", "  system: ultrastable"]
    parent = i.get("parent")
    if parent:
        lines += ["  dependsOn:", f"    - {q('component:default/' + parent.split('/', 1)[1])}"]
    return "\n".join(lines) + "\n"


def _key_span(lines: list[str], key: str):
    """(first, end) of a top-level YAML key and its indented or listed value lines, or None."""
    for n, x in enumerate(lines):
        if re.match(rf"{re.escape(key)}:(\s|$)", x):
            end = n + 1
            while end < len(lines) and lines[end][:1] in (" ", "\t", "-"):
                end += 1
            return n, end
    return None


def citation(text: str | None, i: dict, h: dict, keep=()) -> str:
    """CITATION.cff (Citation File Format 1.2.0). `license` takes an SPDX list id only, so a LicenseRef is given as `license-url`, the text in the
    repository. Keys the format requires and the file lacks are added (the author is the holder LICENSE names); every other key is kept, and so
    is a rendered key named in `keep` that the file already has (the platform's own title and abstract)."""
    ref = i["license"].startswith("LicenseRef-")
    want = {"title": i["name"], "abstract": i["summary"], "repository-code": "https://github.com/" + i["repo"],
            ("license-url" if ref else "license"): license_url(i) if ref else i["license"]}
    if i.get("public_url"):
        want["url"] = i["public_url"]
    lines = text.rstrip("\n").splitlines() if text else []
    required = [("cff-version", ["cff-version: 1.2.0"]), ("message", ['message: "If you use this work, please cite it as below."'])]
    required += [("type", ["type: software"])] if not text else []
    required += [("authors", ["authors:", "  - name: " + json.dumps(h["name"], ensure_ascii=False)])]
    for k, add in required:
        if not _key_span(lines, k):
            lines += add
    gone = _key_span(lines, "license" if ref else "license-url")  # a LicenseRef in `license` fails the format's schema; a stale url misleads
    if gone:
        del lines[gone[0]:gone[1]]
    for k, v in want.items():
        line, sp = f"{k}: {json.dumps(v, ensure_ascii=False)}", _key_span(lines, k)
        if sp and k in keep:
            continue
        lines = lines[:sp[0]] + [line] + lines[sp[1]:] if sp else lines + [line]
    return "\n".join(lines) + "\n"


def llms_txt(root: Path, i: dict, made=RENDERED) -> str:
    """llms.txt (https://llmstxt.org): the name, a one-line summary, then link lists an agent reads first. Files are listed only where they exist
    or this render writes them (`made`)."""
    o = i.get("public_url")
    there = lambda rel: rel in made or (root / rel).is_file()  # noqa: E731
    out = [f"# {i['name']}", "", f"> {i['summary']}", ""]
    if i.get("loop"):
        out += [i["loop"], ""]
    sections = [("Live", [(i["name"], o + "/", "the running system"), ("Health report", o + "/health", "the result of its last tick"),
                          ("Statements", o + "/claims.json", "what it states, and the endpoint behind each statement"),
                          ("llms.txt", o + "/llms.txt", "the index the running system serves, with every route it answers")] if o else [])]
    sections += [(title, [(rel, rel, what) for rel, what in rows if there(rel)]) for title, rows in LLMS_FILES]
    sections += [("Optional", [("Source", "https://github.com/" + i["repo"], "the repository")] +
                  [(rel, rel, what.format(license=i["license"])) for rel, what in LLMS_OPTIONAL if there(rel)])]
    for title, links in sections:
        if links:
            out += [f"## {title}", ""] + [f"- [{t}]({u}): {w}" for t, u, w in links] + [""]
    return "\n".join(out).rstrip("\n") + "\n"


def reuse_toml(i: dict, h: dict) -> str:
    """REUSE.toml (REUSE 3.3): one annotation that gives every file its copyright holder and licence; a file's own SPDX header stays closest."""
    q = lambda s: json.dumps(str(s), ensure_ascii=False)  # noqa: E731  JSON basic strings are TOML basic strings
    who = " ".join(x for x in (h.get("year"), h["name"]) if x)
    return "\n".join(["# Generated by scripts/surfaces.py from ultrastable.json and LICENSE; do not edit. https://reuse.software/spec-3.3/",
                      "version = 1", "", "[[annotations]]", 'path = "**"', 'precedence = "closest"', f"SPDX-FileCopyrightText = {q(who)}",
                      f"SPDX-License-Identifier = {q(i['license'])}"]) + "\n"


def codemeta(i: dict, h: dict) -> str:
    """codemeta.json (CodeMeta 3.0, JSON-LD): the same name, description, repository, licence and holder as CITATION.cff and publiccode.yml."""
    author = {"@type": "Person", "@id": f"https://orcid.org/{h['orcid']}", "name": h["name"]} if h.get("orcid") else {"name": h["name"]}
    doc = {"@context": "https://w3id.org/codemeta/3.0", "@type": "SoftwareSourceCode", "name": i["name"], "description": i["summary"],
           "codeRepository": "https://github.com/" + i["repo"], "url": i.get("public_url") or "https://github.com/" + i["repo"],
           "license": license_url(i), "author": [author], "keywords": sorted(i.get("topics") or [])}
    return json.dumps(doc, indent=1, ensure_ascii=False) + "\n"


def served(root, path: str) -> bool:
    """Whether the kit's Worker at this root answers PATH in public: a route is public only when worker/src/visibility.js lists it among its
    public reads (BOOT-ACCEPT-1), so a page never names a route the Worker does not serve."""
    vis = Path(root) / "worker/src/visibility.js"
    text = vis.read_text(encoding="utf-8") if vis.is_file() else ""
    return any(f"'{path}'" in line for line in re.findall(r"^export const PUBLIC_(?:READS|CONTRACT) = .*$", text, re.M))


def scaffold(root=HERE) -> dict:
    """{path: text} for the community files a repository starts with. Written only when missing (render), never overwritten and never compared
    (check): people and loops add to them. CHANGELOG follows Keep a Changelog 1.1.0, CONTRIBUTING names Conventional Commits 1.0.0, SECURITY
    points at the repository's private vulnerability reporting, and at /.well-known/security.txt (RFC 9116) only when the Worker serves it."""
    root, i = Path(root), identity(root)
    sec = ["# Security", "", "Report a vulnerability privately through GitHub's private vulnerability reporting on this repository: "
           f"https://github.com/{i['repo']}/security/advisories/new. Please do not open a public issue for a vulnerability."]
    if i.get("public_url") and served(root, "/.well-known/security.txt"):
        sec += ["", f"The running system publishes its security contact at {i['public_url']}/.well-known/security.txt (RFC 9116)."]
    con = ["# Contributing", "", "Agents and people follow the same path." + (" Read [AGENTS.md](AGENTS.md) first." if (root / "AGENTS.md").is_file() else ""), "",
           "- Work starts from an issue with a done check and a closing probe.",
           "- Branch, open a pull request, and the server lane merges it when its checks pass.",
           "- Commit titles follow [Conventional Commits 1.0.0](https://www.conventionalcommits.org/en/v1.0.0/), for example `fix(worker): retry merge on 502`.",
           "- Releases follow [Semantic Versioning 2.0.0](https://semver.org/) and are listed in [CHANGELOG.md](CHANGELOG.md).",
           "- Keep secrets out of commits. Report security problems as [SECURITY.md](SECURITY.md) says."]
    sec11 = re.search(r"^\s*(\d+)\.\s+CONTRIBUTIONS\s*$", license_text(root) or "", re.M)
    if sec11:
        con.append(f"- A contribution is made on the terms of [LICENSE](LICENSE), section {sec11.group(1)}.")
    log = ["# Changelog", "", f"All notable changes to {i['name']} are listed here. The format follows [Keep a Changelog 1.1.0](https://keepachangelog.com/en/1.1.0/) "
           "and versions follow [Semantic Versioning 2.0.0](https://semver.org/).", "", "## [Unreleased]"]
    return {"CHANGELOG.md": "\n".join(log) + "\n", "CONTRIBUTING.md": "\n".join(con) + "\n", "SECURITY.md": "\n".join(sec) + "\n"}


def plan(i: dict, what="all") -> dict:
    gh = {"repo": i["repo"], "description": i["summary"], "homepage": i.get("public_url") or "", "topics": sorted(i.get("topics") or []),
          "settings": {**MERGE, "private": i["visibility"] == "private", "is_template": i.get("layer") == "template"}}
    wk = {"ultrastable": 1, "name": i["name"], "url": i.get("public_url"), "repo": "https://github.com/" + i["repo"], "license": i["license"],
          "discoverable": i["visibility"] == "public", "directory": PLATFORM + "/directory", "platform": PLATFORM}
    out = {"github": gh, "wellknown": wk}
    return out if what == "all" else {what: out[what]} if what in out else {}


def problems(root=HERE) -> list[tuple[tuple[str, ...], str]]:
    """(the surfaces that wait, what is missing) for each fact a render that guesses nothing needs and the repository lacks: the licence text, the
    holder it names, and a long enough description. Only those surfaces wait; every other one is rendered, and check() fails on each problem."""
    root, i, out = Path(root), identity(root), []
    lic = license_text(root)
    if lic is None:
        out.append(((f"LICENSES/{i.get('license')}.txt",), f"LICENSE: missing; LICENSES/{i.get('license')}.txt is a copy of it"))
    if not holder(root):
        where = "no" if lic is not None else "missing, so no"
        out.append((HOLDER_FILES, f"LICENSE: {where} \"Licensor:\" or \"Copyright\" line names the copyright holder, and CITATION.cff names no author; "
                                  f"{', '.join(HOLDER_FILES)} wait for the holder, and it is never guessed"))
    if i.get("summary") and len(long_description(i)) < 150:
        own = "description" in ((schema(root).get("properties") or {}).get("identity") or {}).get("properties", {})
        out.append((("publiccode.yml",), f"{MANIFEST}: identity.summary and identity.loop give publiccode.yml a {len(long_description(i))}-character "
                    "longDescription; the standard needs at least 150, and the text is never padded" +
                    ("; write identity.description (150 to 10000 characters) in the system's own words" if own else "")))
    return out


def surfaces(root=HERE) -> dict:
    """{relative path: the text the manifest renders for it}. A surface that waits on a missing fact (problems) maps to None, so a reader reports
    it as unmeasured, never as current; every other surface is rendered."""
    root, i = Path(root), identity(root)
    held = {p for paths, _ in problems(root) for p in paths}
    st, h = stage(root), holder(root)
    rd, ci = root / "README.md", root / "CITATION.cff"
    button = i.get("visibility") == "public" and (root / "wrangler.jsonc").is_file()
    plat = i.get("layer") == "platform"
    # On the platform, the README blocks come from foundation/livelinks.py and its brand sync, catalog-info.yaml from foundation/stdgen.py and the
    # GitHub metadata from foundation/repostd.py repo_metadata; one generator owns each, so this renderer leaves those three alone there. Its
    # CITATION.cff is rendered with the platform's own title, abstract and url kept (PLATFORM_KEEP).
    makers = [("README.md", None if plat else lambda: render_readme(rd.read_text(encoding="utf-8") if rd.is_file() else "", i, st, button)),
              ("publiccode.yml", lambda: publiccode(i, st, h)),
              ("CITATION.cff", lambda: citation(ci.read_text(encoding="utf-8") if ci.is_file() else None, i, h, PLATFORM_KEEP if plat else ())),
              ("llms.txt", lambda: llms_txt(root, i, made)),
              ("REUSE.toml", lambda: reuse_toml(i, h)),
              (f"LICENSES/{i['license']}.txt", lambda: license_text(root)),
              ("codemeta.json", lambda: codemeta(i, h)),
              (GITHUB_PLAN, None if plat else lambda: json.dumps(plan(i, "github")["github"], indent=1, ensure_ascii=False) + "\n"),
              ("catalog-info.yaml", None if plat else lambda: catalog(i, st))]
    made = {rel for rel, fn in makers if fn and rel not in held}
    return {rel: (fn() if rel in made else None) for rel, fn in makers if fn}


def _intake():
    p = HERE / "bootstrap/intake.py"
    if not p.is_file():
        return None
    spec = importlib.util.spec_from_file_location("kit_intake", p)
    m = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(m)
    return m


def birth(root=HERE) -> list[str]:
    """IDENTITY-AT-BIRTH-1: a copy of the template that holds its own idea but still names the template is drift. Needs no network: the template's
    example idea (bootstrap/intake.py is_template) is the only IDEA.md a template-layer manifest may sit beside."""
    root, i = Path(root), identity(root)
    idea, it = root / "IDEA.md", _intake()
    if i.get("layer") == "template" and idea.is_file() and it and not it.is_template(idea.read_text(encoding="utf-8")):
        return [f"{MANIFEST}: still names the template ({i.get('repo')}) while IDEA.md holds this system's own idea; run python3 scripts/surfaces.py --adopt"]
    return []


def check(root=HERE) -> list[str]:
    errs = check_manifest(root)
    if errs:
        return errs
    errs = birth(root) + [msg for _, msg in problems(root)]
    for rel, text in surfaces(root).items():
        f = Path(root) / rel
        if text is None:
            continue  # its problem is listed above
        if not f.is_file():
            errs.append(f"{rel}: missing; run python3 scripts/surfaces.py --render")
        elif f.read_text(encoding="utf-8") != text:
            errs.append(f"{rel}: differs from what {MANIFEST} renders; run python3 scripts/surfaces.py --render")
    return errs


def render(root=HERE) -> list[str]:
    """Write every surface that differs from its render, and each community file that is missing; a surface that waits on a missing fact
    (problems) is left as it is. Raises Unrenderable when the manifest itself is not valid. Running it twice changes nothing."""
    errs = check_manifest(root)
    if errs:
        raise Unrenderable(errs)
    root, wrote = Path(root), []
    for rel, text in scaffold(root).items():  # first: llms.txt lists the files that exist
        f = root / rel
        if not f.is_file():
            f.write_text(text, encoding="utf-8")
            wrote.append(rel)
    for rel, text in surfaces(root).items():
        f = root / rel
        if text is None:
            continue
        if not f.is_file() or f.read_text(encoding="utf-8") != text:
            f.parent.mkdir(parents=True, exist_ok=True)
            f.write_text(text, encoding="utf-8")
            wrote.append(rel)
    return wrote


def own_repo(root=HERE, env=None) -> tuple[str | None, str]:
    """(owner/name, where it was read) of the repository this checkout is, in order: `repo:` in IDEA.md's front matter, GITHUB_REPOSITORY when this
    root is the Action's own checkout (GITHUB_WORKSPACE), then the git remote `origin` when this root is its repository's top level.
    (None, why) when none can be read: a copy of the seed inside another repository is never given that repository's name."""
    env = os.environ if env is None else env
    root = Path(root).resolve()
    idea = root / "IDEA.md"
    front = re.match(r"^---\n(.*?)\n---\n", idea.read_text(encoding="utf-8"), re.S) if idea.is_file() else None
    r = re.search(r"^repo:\s*([A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+)\s*(#.*)?$", front.group(1), re.M) if front else None
    if r:
        return r.group(1), "IDEA.md"
    ws, gr = env.get("GITHUB_WORKSPACE"), env.get("GITHUB_REPOSITORY", "")
    if ws and REPO_RE.fullmatch(gr) and Path(ws).resolve() == root:
        return gr, "GITHUB_REPOSITORY"
    try:
        top = subprocess.run(["git", "-C", str(root), "rev-parse", "--show-toplevel"], capture_output=True, text=True, timeout=20)
        if top.returncode != 0 or Path(top.stdout.strip()).resolve() != root:
            return None, "no repo line in IDEA.md, no GITHUB_REPOSITORY for this checkout, and this folder is not a git repository's top level"
        url = subprocess.run(["git", "-C", str(root), "remote", "get-url", "origin"], capture_output=True, text=True, timeout=20).stdout.strip()
    except (OSError, subprocess.SubprocessError) as e:
        return None, f"git could not be read ({type(e).__name__})"
    m = re.search(r"[:/]([A-Za-z0-9_.-]+)/([A-Za-z0-9_.-]+?)(?:\.git)?/?$", url)  # owner/name only: the URL itself is never printed
    return (f"{m.group(1)}/{m.group(2)}", "git remote origin") if m else (None, "the git remote origin names no owner/name")


def default_summary(name: str) -> str:
    return f"{name}: an autonomous system started from the Ultrastable seed and run by its own managers."


def fit_summary(text) -> str | None:
    """The manifest's summary (20 to 350 characters) from free text, cut at a sentence or a word; None when the text is too short to say anything."""
    s = " ".join(str(text or "").split())
    return short(s, 350) if len(s) >= 20 else None


def adopt(root, repo: str, name: str | None = None, summary: str | None = None, public_url: str | None = None, runs_as: list | None = None,
          visibility: str = "public", visibility_reason: str = "DISCOVER-1: public by default", parent: str = "ultrastable/ultrastable",
          slug: str | None = None) -> list[str]:
    """IDENTITY-AT-BIRTH-1: a repository started from the template takes its own identity, then every surface is rendered from it. The one
    implementation: the platform's fill (foundation/fleetmap.py adopt) and the seed's own boot (bootstrap/bootstrap.py, step adopt) both call it.

    First time (the manifest does not name `repo` yet): the identity is written (layer seeded-system, the template's licence and loop kept), the
    README takes the system's name and drops the template's running example, and the template's CITATION.cff and CHANGELOG.md give way to this
    system's own. After that only where it runs follows (public_url, runs_as when given), and a name adopt took from the repository gives way to
    the owner's own (`name`). Returns the files that changed. Raises ValueError (Unrenderable for an invalid manifest) before anything is written;
    a surface that waits on a missing fact is not rendered, and problems() names it."""
    root = Path(root)
    if not REPO_RE.fullmatch(repo or ""):
        raise ValueError(f"adopt: {repo!r} is not owner/name")
    short_name = repo.split("/", 1)[1]
    p = root / MANIFEST
    cfg = json.loads(p.read_text(encoding="utf-8")) if p.is_file() else {}
    old = cfg.get("identity") or {}
    rd = root / "README.md"
    before = rd.read_text(encoding="utf-8") if rd.is_file() else ""
    name, wrote = (name or "").strip()[:80] or None, []
    if old.get("repo") == repo:
        i = dict(old)
        if public_url:
            i["public_url"], i["status"] = public_url, "live"
        if runs_as:
            i["runs_as"] = runs_as
        renamed = bool(name) and old.get("name") == short_name and name != short_name
        if renamed:
            i["name"] = name
            if old.get("summary") == default_summary(short_name):
                i["summary"] = fit_summary(summary) or default_summary(name)
    else:
        # REUSE-IgnoreStart  (a pattern that reads a licence id, not this file's own licence)
        lic = old.get("license") or (re.search(r"SPDX-License-Identifier:\s*(\S+)", license_text(root) or "") or [None, None])[1]
        # REUSE-IgnoreEnd
        if not lic:
            raise ValueError("adopt: no licence id in ultrastable.json or in LICENSE's SPDX-License-Identifier line; it is never guessed")
        nm = name or short_name
        i = {"name": nm, "slug": slug or (re.sub(r"[^a-z0-9.-]+", "-", short_name.lower()).strip("-")[:63] or "system"),
             "summary": fit_summary(summary) or default_summary(nm), "repo": repo, "public_url": public_url or None, "license": lic, "topics": list(TOPICS),
             "layer": "seeded-system", "parent": parent, "visibility": visibility, "visibility_reason": visibility_reason,
             "status": "live" if public_url else "planned", "loop": old.get("loop", ""), "runs_as": runs_as or []}
        renamed = False
    cfg = {**{k: v for k, v in cfg.items() if k == "$schema_version"}, "identity": i, **{k: v for k, v in cfg.items() if k not in ("$schema_version", "identity")}}
    if isinstance(cfg.get("org"), dict):  # one name, one slug (check_manifest)
        cfg["org"].update({k: i[k] for k in ("name", "slug") if k in cfg["org"]})
    errs = validate(cfg, schema(root))  # the whole manifest, before anything is written: render() would refuse an invalid one after the README moved
    if errs:
        raise Unrenderable(["adopt: the manifest would not be valid: " + "; ".join(errs)])
    text = json.dumps(cfg, indent=2) + "\n"
    if not p.is_file() or p.read_text(encoding="utf-8") != text:
        p.write_text(text, encoding="utf-8")
        wrote.append(MANIFEST)
    if old.get("repo") != repo:
        body = EX_BLOCK.sub("", before, count=1)
        for block in ("identity", "how"):
            body = _re(block).sub("", body, count=1)
        h = re.search(r"^# .*\n", body, re.M)
        rest = (body[h.end():] if h else body).lstrip("\n")
        rd.write_text(f"# {i['name']}\n\n" + (rest if INTRO in rest else INTRO + "\n" + rest), encoding="utf-8")
        cit = root / "CITATION.cff"
        if cit.is_file() and (old.get("repo") or "ultrastable/seed") in cit.read_text(encoding="utf-8"):
            cit.unlink()  # the template's citation is not this system's; the render writes its own
        log = root / "CHANGELOG.md"
        if log.is_file():  # the template's history is not this system's; its own starts at [Unreleased]
            log.write_text(scaffold(root)["CHANGELOG.md"], encoding="utf-8")
            wrote.append("CHANGELOG.md")
    elif renamed and before.startswith(f"# {short_name}\n"):
        rd.write_text(f"# {i['name']}\n" + before[len(f"# {short_name}\n"):], encoding="utf-8")
    wrote += render(root)
    after = rd.read_text(encoding="utf-8") if rd.is_file() else ""
    return sorted({w for w in wrote if w != "README.md"} | ({"README.md"} if after != before else set()))


def main(argv=None) -> int:
    av = list(sys.argv[1:] if argv is None else argv)
    root = Path(av[av.index("--root") + 1]) if "--root" in av else HERE
    arg = lambda k: av[av.index(k) + 1] if k in av and av.index(k) + 1 < len(av) else None  # noqa: E731
    if "--validate" in av:
        errs = check_manifest(root)
        print("\n".join(errs) or f"{MANIFEST}: valid")
        return 1 if errs else 0
    if "--check" in av:
        errs = check(root)
        print("\n".join("FAIL " + e for e in errs) or "surfaces ok: every surface equals what the manifest renders")
        return 1 if errs else 0
    def waiting() -> int:  # a surface held back by a missing fact is named, and the command is not green while one waits
        gaps = problems(root)
        for _, msg in gaps:
            print("WAIT " + msg, file=sys.stderr)
        return 1 if gaps else 0
    if "--render" in av:
        try:
            wrote = render(root)
        except Unrenderable as e:
            print(f"surfaces --render: nothing written: {e}", file=sys.stderr)
            return 1
        print("surfaces: " + (", ".join(wrote) + " written" if wrote else "nothing to change"))
        return waiting()
    if "--adopt" in av:
        repo, where = (arg("--repo"), "--repo") if arg("--repo") else own_repo(root)
        if not repo:
            print(f"surfaces --adopt: this checkout's repository could not be read ({where}); nothing changed", file=sys.stderr)
            return 1
        if repo in TEMPLATE_REPOS:
            print(f"surfaces --adopt: {repo} is the template or the platform itself and keeps its own identity; nothing changed")
            return 0
        try:
            wrote = adopt(root, repo, name=arg("--name"), summary=arg("--summary"), public_url=arg("--public-url"))
        except ValueError as e:
            print(f"surfaces --adopt: nothing changed: {e}", file=sys.stderr)
            return 1
        print(f"surfaces --adopt: {repo} (read from {where}): " + (", ".join(wrote) + " written" if wrote else "nothing to change"))
        return waiting()
    if "--plan" in av:
        k = av.index("--plan")
        what = av[k + 1] if len(av) > k + 1 and not av[k + 1].startswith("--") else "all"
        errs = check_manifest(root)
        if errs:
            print("\n".join(errs), file=sys.stderr)
            return 1
        i = identity(root)
        if what == "publiccode":
            bad = [msg for paths, msg in problems(root) if "publiccode.yml" in paths]
            if bad:
                print("\n".join(bad), file=sys.stderr)
                return 1
            sys.stdout.write(publiccode(i, stage(root), holder(root)))
        else:
            print(json.dumps(plan(i, what), indent=1, ensure_ascii=False))
        return 0
    print(__doc__)
    return 2


if __name__ == "__main__":
    raise SystemExit(main())
